// Nodo "Validar pedido" — EDITÁ LA CLAVE (tiene que ser la misma que pongas en dashboard/config.local.js).
const CLAVE = 'cambiar-esta-clave';

const b = $input.first().json.body || {};
const error = (mensaje) => [{ json: { accion: 'error', mensaje } }];
if (String(b.clave || '') !== CLAVE) return error('Clave incorrecta.');
if (!['emparejar', 'guardar'].includes(b.accion)) return error('Acción desconocida.');
if (!Array.isArray(b.filas) || !b.filas.length) return error('No llegaron filas.');
if (b.filas.length > 3000) return error('Demasiadas filas (máximo 3000).');

const txt = (s, max) => (s == null ? null : String(s).trim().slice(0, max) || null);
if (b.accion === 'guardar') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(b.vigencia || ''))) return error('Falta la fecha de vigencia.');
  const filas = b.filas
    .map((f) => ({ ean: txt(f.ean, 20), precio: Number(f.precio), zona_id: txt(f.zona_id, 40),
      retailer_id: txt(f.retailer_id, 40), descripcion: txt(f.descripcion, 200) }))
    .filter((f) => /^\d{8,14}$/.test(f.ean || '') && f.precio > 0);
  if (!filas.length) return error('Ninguna fila tiene EAN y precio válidos.');
  return [{ json: { accion: 'guardar', filas: JSON.stringify(filas), vigencia: b.vigencia, lote: txt(b.lote, 120), cantidad: filas.length } }];
}
// emparejar: filas sin EAN → la IA busca a qué producto del catálogo corresponde cada una
const filas = b.filas.slice(0, 400).map((f, i) => ({ i: Number.isInteger(f.i) ? f.i : i, descripcion: txt(f.descripcion, 200) }))
  .filter((f) => f.descripcion);
if (!filas.length) return error('Las filas no tienen descripción.');
return [{ json: { accion: 'emparejar', filas } }];

// Nodo "Armar pedido a Gemini" — empareja descripciones del archivo con productos del catálogo (Gemini gratis).
const pedido = $('Validar pedido').first().json;
const catalogo = $input.all().map((i) => i.json).filter((p) => p && p.ean);

const sistema = `Sos analista de datos maestros de PepsiCo Argentina (snacks).
Te paso (A) filas de una lista de precios sugeridos, identificadas por un número, y (B) el catálogo de productos con su EAN.
Para cada fila de A indicá el EAN del producto de B que es EXACTAMENTE el mismo (misma marca, misma variedad o sabor y mismo gramaje; tolerá diferencias de hasta 5 g y abreviaturas como "LAY CLAS 85").
Si no hay un producto que coincida con seguridad, devolvé ean null: es preferible dejar una fila sin emparejar que emparejarla mal.
Respondé SOLO un array JSON con objetos {"i": número, "ean": "…" o null}.`;

const a = pedido.filas.map((f) => `${f.i} | ${f.descripcion}`).join('\n');
const b = catalogo.map((p) => `${p.ean} | ${p.producto || ''} | ${p.marca || ''} | ${p.gramaje_g != null ? Number(p.gramaje_g) + ' g' : ''}`).join('\n');

return [{ json: {
  eans: catalogo.map((p) => String(p.ean)),
  body: {
    systemInstruction: { parts: [{ text: sistema }] },
    contents: [{ role: 'user', parts: [{ text: `A) Filas de la lista (número | descripción):\n${a}\n\nB) Catálogo (EAN | producto | marca | gramaje):\n${b}` }] }],
    generationConfig: { temperature: 0, responseMimeType: 'application/json', maxOutputTokens: 8000 },
  },
} }];

// Nodo "Leer respuesta" — valida que cada EAN devuelto exista en el catálogo.
const res = $input.first().json;
const validos = new Set($('Armar pedido a Gemini').first().json.eans || []);
const texto = ((((res.candidates || [])[0] || {}).content || {}).parts || []).map((p) => p.text || '').join('');
const ini = texto.indexOf('[');
const fin = texto.lastIndexOf(']');
let arr = [];
if (ini >= 0 && fin > ini) { try { arr = JSON.parse(texto.slice(ini, fin + 1)); } catch (e) { arr = []; } }
const filas = (Array.isArray(arr) ? arr : [])
  .filter((x) => x && Number.isInteger(Number(x.i)))
  .map((x) => ({ i: Number(x.i), ean: x.ean != null && validos.has(String(x.ean)) ? String(x.ean) : null }));
return [{ json: { ok: true, filas, emparejadas: filas.filter((f) => f.ean).length } }];
